async delete(key: string): Promise<boolean> {
  this.l1.delete(key);
  const removed = (await this.call("delete", key, () => this.redis.set(this.prefix + key, TOMBSTONE, this.tombstoneMs, false))) !== FAILED;
  const told = await this.invalidateOthers(key);
  return removed && told;
}

