export async function updateProduct(id: string, patch: Partial<Product>) {
  await db.products.update(id, patch);
  const results = await Promise.allSettled(regionCaches.map((c) => c.delete(id))); // each region: its own TwoLevelCache
  for (const r of results) if (r.status !== "fulfilled" || r.value === false) logger.warn({ id }, "region cache not invalidated");
}

